solution.code:
import heapq


class KthLargest:
    def __init__(self, k: int, scores: list[int]):
        self.k = k
        self.heap: list[int] = []
        for s in scores:
            self._push(s)

    def _push(self, score: int) -> None:
        if len(self.heap) < self.k:
            heapq.heappush(self.heap, score)
        elif score > self.heap[0]:
            heapq.heapreplace(self.heap, score)

    def add(self, score: int) -> int | None:
        self._push(score)
        return self.heap[0] if len(self.heap) == self.k else None
